import{_ as r,o as a,a as i,b as t}from"./app.DKoEZOcr.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD与SIMT混合算子实现","link":"/guide/operator_practice/simd_simt_hybrid_operator_impl/simd_simt_hybrid_operator_impl"},{"text":"基础知识","link":"/guide/operator_practice/simd_simt_hybrid_operator_impl/basics"}]},"headers":[],"relativePath":"guide/operator_practice/simd_simt_hybrid_operator_impl/basics.md","filePath":"guide/operator_practice/simd_simt_hybrid_operator_impl/basics.md","lastUpdated":1787050286000}'),_={name:"guide/operator_practice/simd_simt_hybrid_operator_impl/basics.md"};function o(m,e,p,d,c,s){return a(),i("div",null,[...e[0]||(e[0]=[t('<div><article class="markdown-body"><h1>基础知识<span id="ZH-CN_TOPIC_0000002532388147"></span></h1><p>本节内容为使用<a href="../../../api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute.html">Reg矢量计算API</a>和<a href="../../../api/SIMT-API/SIMT-API.html">SIMT API</a>进行SIMD与SIMT混合编程的指导。</p><p>在<a href="../../programming_guide/advanced_programming/hardware_implementation/basic_architecture.html">Vector Core</a>中，SIMT单元和SIMD单元共享片上存储，因此可以利用片上存储Unified Buffer（UB）完成SIMD与SIMT混合编程，具体硬件架构的介绍请参考<a href="../../programming_guide/advanced_programming/hardware_implementation/architecture_spec/npu_arch_3510.html">NPU架构版本3510</a>。在进行后续内容的学习前，请先了解SIMD与SIMT混合编程的编程模型：<a href="../../programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/overview.html">SIMD与SIMT混合编程</a>。</p><p><a href="../../programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/reg_vector_computation.html">SIMD编程</a>提供了基于寄存器（Regbase）开发的Reg矢量计算API，Reg矢量计算API可以直接操作Vector Core中的SIMD寄存器，API单次处理的数据量上限等于寄存器的大小，通过<a href="../../../api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetVecLen.html">GetVecLen</a>接口获取该值。在算子实现中，需要多次调用Reg矢量计算API完成对单核数据的处理。</p><p>与SIMD编程不同的是，在SIMT编程中Global Memory上的数据可以被直接读取和使用。SIMT编程常通过组织线程的层次结构来实现数据的切分，使用threadIdx等<a href="../../programming_guide/language_extension/simt_builtin_keywords.html">SIMT BuiltIn关键字</a>计算线程应处理的数据索引，完成索引对应数据的计算，从而将函数实现简化为标量计算。</p></article></div>',1)])])}const l=r(_,[["render",o]]);export{g as __pageData,l as default};
